using System;using System.IO;using System.Reflection;using System.Data.Common;
class InspectOrderLinks{static int Main(string[]args){try{var a=Assembly.LoadFrom(Path.GetFullPath(args[0]));using(var c=(DbConnection)a.GetType("PineTree.Classes.DB").GetMethod("CreateConnection").Invoke(null,null)){c.Open();foreach(var sql in new[]{"SHOW CREATE TABLE OrderInfo","SELECT COUNT(*) FROM OrderInfo WHERE OrderNo REGEXP '_[0-9]+$'"}){using(var q=c.CreateCommand()){q.CommandText=sql;using(var r=q.ExecuteReader()){while(r.Read())Console.WriteLine(r.GetValue(r.FieldCount-1));}}}}return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}
